\label{Aristotle:lemma:3A}
Let $A = \{a,b,c\}$, where  $a,b,c$ are integers satisfying $a < b < c$ and $a < 0$,  
and let $x = b-a$ and $y = c-a$.  
Then $n \in hA$ if and only if there exist nonnegative integers $s_n$ and $t_n$ such that 
\begin{equation}            \label{Aristotle:3Aineq}
s_n + t_n \leq h 
\end{equation}
and 
\begin{equation}            \label{Aristotle:3Asum}
n = ha + s_nx+t_ny.
\end{equation}

\label{Aristotle:lemma:xya}
Let $A = \{a,b,c\}$, where  $a,b,c$ are integers satisfying $a < b < c$,  
and let $x = b-a$ and $y = c-a$.   
If $[0,h+1] \subseteq hA$, then 
\begin{equation}                           \label{Aristotle:xya-y}
1 \leq x < y \leq h+1
\end{equation}
and 
\begin{equation}                           \label{Aristotle:xya-gcd}
\gcd(x,y) = 1
\end{equation}
and 
\begin{equation}                           \label{Aristotle:xya-a}
 a \geq -(h-1). 
\end{equation}
For all $n \in hA$, 
\begin{equation}                           \label{Aristotle:xya-n}
 -h-1 + \frac{n}{h} \leq a. 
\end{equation}
